# greedy forward selection at fixed w
def greedy(w,maxk=8):
    sel=['1','c','s']
    for _ in range(maxk):
        best=None
        for k in allk:
            if k in sel: continue
            try:
                e,_=fitkeys(w,sel+[k])
            except Exception: continue
            if not np.isfinite(e): continue
            if best is None or e<best[0]: best=(e,k)
        sel.append(best[1])
    e,b=fitkeys(w,sel)
    return e,sel,np.round(b,4)
